// cv/buildCvHtml.js
// Statik şablonu veri-güdümlü hale getiren motor (çok dilli + RTL).
// Kullanım:  import { buildCvHtml } from './cv/buildCvHtml';
//            const html = buildCvHtml(userData, 'ru');  // ikinci parametre hedef dil
import { t } from '../i18n/ui';
import { dirOf } from '../i18n/languages';
import { formatExperienceDate, formatEducationDate } from '../lib/cvDates';
import {
  labelOf, NATION_LABELS, EDU_LABELS,
  POSITION_LABELS, SKILL_LABELS, LANG_LABELS, LEVEL_LABELS, LICENSE_WORD_LABELS,
  bloodLabel,
} from './options';

// --- Filigran (orijinal şablonun .main arka planındaki büyük soluk logo) ---
// Base64 doğrudan buraya gömülü; ayrı dosya/import gerekmez.
// Filigranı KALDIRMAK istersen bu satırı:  const WATERMARK_BG = '';  yap.
const WATERMARK_BG =
  'data:image/png;base64,';

// HTML'e güvenli enjeksiyon (kullanıcı girdisi & < > " içerebilir)
const esc = (v) =>
  String(v ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');

// Değer boşsa orijinaldeki gibi &nbsp; bırak
const val = (v) => (v && String(v).trim() ? esc(v) : '&nbsp;');

// Bir kişisel-bilgi satırı (ikon + etiket + değer)
const infoItem = (icon, label, value) => `
      <div class="info-item"><span class="ic">${icon}</span><div><div class="label">${esc(label)}</div><div class="value">${val(value)}</div></div></div>`;

// Zaman çizelgesi öğesi (iş / eğitim)
const timelineItem = (date, title, sub) => `
        <div class="tl-item">
          <div class="tl-date">${esc(date)}</div>
          <div class="tl-body">
            <div class="t">${esc(title)}</div>
            <div class="s">${esc(sub)}</div>
          </div>
        </div>`;

export function buildCvHtml(data = {}, lang = 'tr', { withLogo = true, masked = false, videoUrl = '' } = {}) {
  const d = data;
  // Acente görünümü: iletişim + aile bilgileri bulanıklaştırılır (gerçek veri zaten maskelenmiş gelir).
  const maskCss = masked
    ? '.contacts .c:not(.candno) .tx, .fam-group .lg{filter:blur(5px);-webkit-filter:blur(5px);user-select:none;}'
    : '';
  const L = (key, vars) => t(key, lang, vars);     // arayüz metni kısayolu
  const dir = dirOf(lang);                           // 'ltr' | 'rtl'
  const fullName = `${esc(d.firstName || '')}<br>${esc(d.lastName || '')}`;

  // --- Diller (dil adı + seviye dile çevrilir) ---
  const langs = (d.languages || [])
    .filter((l) => l && (l.name || l.level))
    .map((l) => `<div class="lg"><b>${esc(labelOf(LANG_LABELS, l.name, lang))}</b> — ${esc(labelOf(LEVEL_LABELS, l.level, lang))}</div>`)
    .join('\n          ');

  // --- İş deneyimleri (şirket/pozisyon serbest metin; tarih olduğu gibi) ---
  const experience = (d.experience || [])
    .filter((e) => e && (e.company || e.position || e.date))
    .map((e) => timelineItem(formatExperienceDate(e, lang), e.company, e.position))
    .join('');

  // --- Eğitim (okul/açıklama serbest metin) ---
  const education = (d.education || [])
    .filter((e) => e && (e.school || e.description || e.date))
    .map((e) => timelineItem(formatEducationDate(e, lang), e.school, e.description))
    .join('');

  // --- Beceriler: kontrollü değerler -> dile çevrilir ---
  const skillsHtml = (d.skills || [])
    .filter((x) => x && String(x).trim())
    .map((x) => `<li>${esc(labelOf(SKILL_LABELS, x, lang))}</li>`)
    .join('\n          ');

  // --- Pozisyonlar: kontrollü değerler -> dile çevrilir ---
  const positionsHtml = (d.positions || [])
    .filter((x) => x && String(x).trim())
    .map((x) => `<li>${esc(labelOf(POSITION_LABELS, x, lang))}</li>`)
    .join('\n          ');

  // --- Sertifikalar: {name, institution} serbest metin ---
  const certText = (c) =>
    typeof c === 'string'
      ? c
      : [c?.name, c?.institution].filter((x) => x && String(x).trim()).join(' — ');
  const certs = (d.certificates || []).filter((c) => certText(c).trim());
  const certHtml = certs.length
    ? certs.map((c) => `<li>${esc(certText(c))}</li>`).join('\n          ')
    : Array(3)
        .fill(`<li class="ph">${esc(L('f_cert_name'))} — ${esc(L('f_cert_inst'))}</li>`)
        .join('\n          ');

  // --- Kontrollü kişisel değerler -> dile çevrilir ---
  const nationalityLabel = labelOf(NATION_LABELS, d.nationality, lang);
  const licenseLabel = labelOf(LICENSE_WORD_LABELS, d.driverLicense, lang); // harf kodları aynen döner
  const bloodTypeLabel = bloodLabel(d.bloodType, d.bloodCountry); // kan grubu ülkesinin stiline göre; CV'de ülke gösterilmez

  const fam = d.family || { mother: {}, father: {} };
  const photoTag = d.photo
    ? `<img class="photo" src="${esc(d.photo)}" alt="${esc(d.firstName)} ${esc(d.lastName)}">`
    : `<div class="photo" style="background:#2c3a4e;"></div>`;

  // --- Tanıtım fotoğrafları (boydan / yakın) -> ayrı 2. sayfa. İkisi de boşsa sayfa eklenmez. ---
  // 2. sayfa: yakın çekim + boydan (vesikalık burada YOK; o 1. sayfada). Alt alta, büyük.
  const extraShots = [
    { uri: d.photoClose, cap: L('photo_cap_close') },
    { uri: d.photoFull, cap: L('photo_cap_full') },
  ].filter((p) => p.uri);
  // Tanıtım videosu (20 sn) — yalnız ekranda; PDF'te videoUrl boş gelir.
  const videoBlock = videoUrl
    ? `<div style="margin:0 0 22px;">
      <div class="photos-title" style="margin-bottom:10px;">${esc(L('intro_video_cv_label'))}</div>
      <video src="${esc(videoUrl)}" controls playsinline preload="metadata" style="width:100%;max-height:360px;border-radius:16px;background:#000;display:block;"></video>
    </div>`
    : '';
  const photosPage = (extraShots.length || videoUrl)
    ? `
  <div class="page photos-page">
    <div class="photos-head">
      <h1>${esc(d.firstName || '')} ${esc(d.lastName || '')}</h1>
      <div class="photos-title">${esc(L('sec_photos_extra'))}</div>
    </div>
    ${videoBlock}
    <div class="photos-grid shots-${extraShots.length}">
      ${extraShots.map((p) => `<figure class="shot"><img src="${esc(p.uri)}" alt="${esc(p.cap)}"><figcaption>${esc(p.cap)}</figcaption></figure>`).join('\n      ')}
    </div>
  </div>`
    : '';

  const mainBg = (withLogo && WATERMARK_BG)
    ? `background-image:url('${WATERMARK_BG}');background-repeat:no-repeat;background-position:center 50%;background-size:80%;`
    : '';

  return `<!DOCTYPE html>
<html lang="${lang}" dir="${dir}">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=900">
<title>${esc(d.firstName)} ${esc(d.lastName)}${d.title ? ` — ${esc(d.title)}` : ''} - CV</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Barlow:wght@300;400;500;600;700;800&family=Barlow+Semi+Condensed:wght@600;700;800&display=swap" rel="stylesheet">
<style>
  :root{
    --sidebar:#1b2533;
    --sidebar-2:#202b3b;
    --main:#ffffff;
    --ink:#1b2533;
    --muted:#737373;
    --muted-2:#9aa1ac;
    --accent:#c2a25a;
    --bar-track:#b6b6b6;
    --line:#d6d6d6;
  }
  *{margin:0;padding:0;box-sizing:border-box;}
  html,body{background:#ffffff;font-family:'Barlow',sans-serif;-webkit-print-color-adjust:exact;print-color-adjust:exact;}
  .page{
    width:900px;min-height:1273px;margin:0px auto;background:var(--main);
    display:grid;grid-template-columns:248px 1fr;
    box-shadow:0 18px 50px rgba(0,0,0,.35);overflow:hidden;
  }
  /* Grid/flex çocuklarının içeriğe göre genişlemesini engelle (taşma koruması) */
  .page > *, .topbar > *, .tl-item > *{min-width:0;}
  .main, .side{min-width:0;overflow:hidden;}
  /* Uzun kelime / boşluksuz metinler sütunu patlatmasın */
  .profile-text, .tl-body .t, .tl-body .s, .plist li,
  .side-langs .lg, .info-item .value, .contacts .c .tx{
    overflow-wrap:anywhere;word-break:break-word;
  }

  /* ---------- SIDEBAR ---------- */
  .side{background:var(--sidebar);color:#fff;padding:26px 20px 40px;}
  .photo-wrap{display:flex;justify-content:center;margin-bottom:30px;}
  .photo{
    width:100%;aspect-ratio:1/1;border-radius:6px;object-fit:cover;
    border:4px solid #2c3a4e;box-shadow:0 6px 18px rgba(0,0,0,.4);
  }
  .side h2, .side .side-sub{
    font-family:'Barlow Semi Condensed',sans-serif;font-weight:700;
    letter-spacing:1.2px;text-transform:uppercase;font-size:17px;
    text-align:center;color:#f3f3f3;white-space:nowrap;
  }
  .side h2{margin-bottom:20px;}
  .side .side-sub{margin-top:40px;margin-bottom:14px;}
  .info-item{display:flex;gap:14px;margin-bottom:15px;align-items:flex-start;}
  .info-item .ic{
    color:var(--accent);font-size:15px;width:18px;text-align:center;
    flex:0 0 18px;margin-top:2px;
  }
  .info-item .label{font-weight:700;font-size:14px;letter-spacing:.4px;color:#fff;line-height:1.25;}
  .info-item .value{font-weight:300;font-size:13.5px;color:#aeb6c2;line-height:1.3;margin-top:1px;}

  .side-langs{margin-top:6px;}
  .side-langs .lg{font-weight:300;font-size:13.5px;color:#aeb6c2;margin-bottom:7px;}
  .side-langs .lg b{font-weight:700;color:#fff;}
  .fam-head{font-weight:700;font-size:16px;color:#fff;margin-bottom:7px;letter-spacing:.4px;}
  .fam-group{margin-bottom:16px;}
  .fam-group .lg{padding-left:0;margin-bottom:8px;}

  /* ---------- MAIN ---------- */
  .main{padding:32px 46px 36px;${mainBg}}
  .topbar{display:flex;justify-content:space-between;align-items:flex-start;gap:28px;
    border-bottom:3px solid var(--ink);padding-bottom:14px;margin-bottom:22px;}
  .name{flex:1 1 auto;min-width:0;padding-right:10px;}
  .name h1{
    font-family:'Barlow Semi Condensed',sans-serif;font-weight:800;
    font-size:46px;line-height:.98;color:var(--ink);letter-spacing:.5px;
  }
  .name .headline{
    margin-top:18px;font-weight:700;font-size:14px;letter-spacing:.8px;
    text-transform:uppercase;color:#5c6570;
    overflow-wrap:anywhere;word-break:break-word;
  }
  /* İletişim: ikon yazının SAĞINDA, blok en sağa hizalı (orijinal şablon) */
  .contacts{flex:0 0 auto;max-width:235px;padding-top:6px;}
  .contacts .c{display:flex;align-items:flex-start;gap:9px;font-size:13px;color:#4a4a4a;margin-bottom:9px;justify-content:flex-end;}
  .contacts .c .tx{text-align:right;word-break:break-word;line-height:1.35;}
  .contacts .c .ic{color:var(--ink);font-size:13px;width:16px;text-align:center;flex:0 0 16px;margin-top:1px;}
  .contacts .c.candno{margin-top:4px;}
  .contacts .c.candno .tx{font-size:16px;font-weight:800;color:var(--ink);letter-spacing:.3px;}
  .contacts .c.candno .ic{font-size:15px;}

  .section{margin-bottom:18px;}
  .section-head{display:flex;align-items:center;gap:12px;margin-bottom:6px;}
  .section-head .ic{font-size:21px;color:var(--muted);}
  .section-head h3{
    font-family:'Barlow Semi Condensed',sans-serif;font-weight:800;
    font-size:26px;color:var(--muted);letter-spacing:.5px;
  }
  .rule{height:2px;background:var(--line);margin-bottom:13px;}

  .profile-text{font-size:14px;line-height:1.55;color:#5a5a5a;font-weight:400;white-space:normal;}

  /* timeline */
  .tl-item{display:grid;grid-template-columns:120px 1fr;gap:0;padding:5px 0;}
  .tl-date{font-weight:700;font-size:14px;color:var(--ink);text-align:center;padding-top:2px;}
  .tl-body{border-left:2px solid #bdbdbd;padding-left:22px;padding-bottom:5px;}
  .tl-body .t{font-weight:700;font-size:16px;color:var(--ink);}
  .tl-body .s{font-weight:400;font-size:14px;color:var(--muted);margin-top:2px;}

  /* lists */
  .plist{list-style:none;}
  .plist li{display:flex;align-items:center;gap:11px;font-weight:700;font-size:15px;color:var(--ink);margin-bottom:9px;}
  .plist li::before{content:'';width:8px;height:8px;border-radius:50%;background:var(--ink);flex:0 0 8px;}
  .plist.cols2{display:grid;grid-template-columns:1fr 1fr;column-gap:26px;row-gap:0;}
  .plist li.ph{color:#9a9a9a;font-weight:500;font-style:italic;}
  .plist li.ph::before{background:#bdbdbd;}

  /* ---------- TANITIM FOTOĞRAFLARI SAYFASI ---------- */
  .photos-page{
    display:block;grid-template-columns:none;background:var(--main);
    padding:46px 56px;
  }
  .photos-head{border-bottom:3px solid var(--ink);padding-bottom:14px;margin-bottom:30px;}
  .photos-head h1{
    font-family:'Barlow Semi Condensed',sans-serif;font-weight:800;
    font-size:40px;line-height:1;color:var(--ink);letter-spacing:.5px;
  }
  .photos-title{
    margin-top:12px;font-weight:700;font-size:14px;letter-spacing:.8px;
    text-transform:uppercase;color:var(--muted);
  }
  /* Alt alta (dikey), büyük: yakın çekim + boydan */
  .photos-grid{display:flex;flex-direction:column;gap:22px;justify-content:flex-start;align-items:center;}
  .shot{display:flex;flex-direction:column;align-items:center;width:auto;}
  .shot img{
    height:470px;width:auto;aspect-ratio:3/4;object-fit:cover;border-radius:8px;
    border:4px solid #2c3a4e;box-shadow:0 8px 22px rgba(0,0,0,.32);background:#e9ebee;
  }
  .shot figcaption{
    margin-top:12px;text-align:center;font-weight:700;font-size:15px;
    letter-spacing:.6px;text-transform:uppercase;color:var(--muted);
  }

@media print{
  @page{size:A4;margin:0;}
  html,body{background:#fff;}
  /* CV 900x1273 (A4 oranı) tasarlandı; sıkıştırmak yerine ORANTILI küçült (zoom layout'u da
     ölçekler, kesmez, sayfalamayı korur). 794/900 = 0.882 -> tam A4 genişliği. */
  .page{margin:0 auto;box-shadow:none;width:900px;min-height:1273px;height:auto;overflow:visible;zoom:0.8;}
  .photos-page{page-break-before:always;break-before:page;}
  /* İki dikey foto tek A4 sayfaya sığsın */
  .photos-grid{gap:12px;}
  .shot img{height:128mm;}
  .shot figcaption{font-size:11px;margin-top:5px;}
}

  /* ---------- RTL (Farsça): tasarım aynı, yalnızca yön aynalanır ---------- */
  [dir="rtl"] .page{grid-template-columns:1fr 248px;}      /* sidebar sağa */
  [dir="rtl"] .side{order:2;}
  [dir="rtl"] .main{order:1;}
  [dir="rtl"] .info-item{flex-direction:row-reverse;}
  [dir="rtl"] .info-item .ic{text-align:center;}
  [dir="rtl"] .side h2, [dir="rtl"] .side .side-sub{ }       /* zaten ortalı */
  [dir="rtl"] .contacts .c{justify-content:flex-start;flex-direction:row-reverse;}
  [dir="rtl"] .contacts .c .tx{text-align:left;}
  [dir="rtl"] .name h1, [dir="rtl"] .name .headline{text-align:right;}
  [dir="rtl"] .tl-item{grid-template-columns:1fr 120px;}
  [dir="rtl"] .tl-body{border-left:none;border-right:2px solid #bdbdbd;padding-left:0;padding-right:22px;}
  [dir="rtl"] .plist li{flex-direction:row-reverse;}
  [dir="rtl"] .section-head{flex-direction:row-reverse;}
  ${maskCss}
</style>
</head>
<body>
  <div class="page">
    <!-- SIDEBAR -->
    <aside class="side">
      <div class="photo-wrap">
        ${photoTag}
      </div>
      <h2>${esc(L('sec_personal'))}</h2>
${infoItem('&#128197;', L('sec_birth'), d.birthDate)}
${infoItem('&#128207;', L('sec_hw'), d.heightWeight)}
${bloodTypeLabel ? infoItem('&#129656;', L('f_blood'), bloodTypeLabel) : ''}
${infoItem('&#127758;', L('f_nationality'), nationalityLabel)}
${infoItem('&#128663;', L('f_lic_class'), licenseLabel)}

      <div class="info-item"><span class="ic">&#9873;</span><div style="width:100%">
        <div class="label" style="margin-bottom:8px;">${esc(L('step_languages'))}</div>
        <div class="side-langs">
          ${langs}
        </div>
      </div></div>

      <h3 class="side-sub">${esc(L('step_family'))}</h3>
      <div class="side-langs">
        <div class="fam-group">
          <div class="fam-head">${esc(L('parent_mother'))}:</div>
          <div class="lg"><b>${esc(L('f_firstName'))}:</b> ${val(fam.mother?.name)}</div>
          <div class="lg"><b>${esc(L('f_lastName'))}:</b> ${val(fam.mother?.lastName)}</div>
          <div class="lg"><b>${esc(L('f_phone'))}:</b> ${val(fam.mother?.phone)}</div>
        </div>
        <div class="fam-group">
          <div class="fam-head">${esc(L('parent_father'))}:</div>
          <div class="lg"><b>${esc(L('f_firstName'))}:</b> ${val(fam.father?.name)}</div>
          <div class="lg"><b>${esc(L('f_lastName'))}:</b> ${val(fam.father?.lastName)}</div>
          <div class="lg"><b>${esc(L('f_phone'))}:</b> ${val(fam.father?.phone)}</div>
        </div>
      </div>
    </aside>

    <!-- MAIN -->
    <main class="main">
      <div class="topbar">
        <div class="name">
          <h1>${fullName}</h1>
          ${d.title ? `<div class="headline">${esc(d.title)}</div>` : ''}
        </div>
        <div class="contacts">
          <div class="c"><span class="tx">${esc(d.email)}</span><span class="ic">&#9993;</span></div>
          <div class="c"><span class="tx">${esc(d.phone)}</span><span class="ic">&#9742;</span></div>
          <div class="c"><span class="tx">${esc(d.location)}</span><span class="ic">&#128205;</span></div>
          ${d.candidateNo ? `<div class="c candno"><span class="tx"><b>${esc(L('candidate_no'))}:</b> ${esc(d.candidateNo)}</span><span class="ic">&#35;</span></div>` : ''}
        </div>
      </div>

      <section class="section">
        <div class="section-head"><span class="ic">&#9776;</span><h3>${esc(L('sec_profile'))}</h3></div>
        <div class="rule"></div>
        <p class="profile-text">${esc(d.profile)}</p>
      </section>

      <section class="section">
        <div class="section-head"><span class="ic">&#10033;</span><h3>${esc(L('step_experience'))}</h3></div>
        <div class="rule"></div>${experience}
      </section>

      <section class="section">
        <div class="section-head"><span class="ic">&#127891;</span><h3>${esc(L('step_education'))}</h3></div>
        <div class="rule"></div>${education}
      </section>

      <section class="section">
        <div class="section-head"><span class="ic">&#10039;</span><h3>${esc(L('sec_skills'))}</h3></div>
        <div class="rule"></div>
        <ul class="plist cols2">
          ${skillsHtml}
        </ul>
      </section>

      <section class="section">
        <div class="section-head"><span class="ic">&#128196;</span><h3>${esc(L('sec_certs'))}</h3></div>
        <div class="rule"></div>
        <ul class="plist">
          ${certHtml}
        </ul>
      </section>

      <section class="section" style="margin-bottom:0;">
        <div class="section-head"><span class="ic">&#9733;</span><h3>${esc(L('sec_positions'))}</h3></div>
        <div class="rule"></div>
        <ul class="plist cols2">
          ${positionsHtml}
        </ul>
      </section>
    </main>
  </div>${photosPage}
</body>
</html>`;
}
